const COMPONENTS = [{"id": "PERMIT", "name": "Building Permits", "fred": "PERMIT", "invert": false, "yoy": -5.0, "z": -0.45, "since": 1960, "lead": 17, "tag": "LEADS", "live": true}, {"id": "HOUST", "name": "Housing Starts", "fred": "HOUST", "invert": false, "yoy": -6.0, "z": -0.5, "since": 1959, "lead": 14, "tag": "LEADS", "live": true}, {"id": "MSACSR", "name": "Monthly Supply of New Houses", "fred": "MSACSR", "invert": true, "yoy": 8.0, "z": -0.55, "since": 1963, "lead": 18, "tag": "LEADS", "live": true}, {"id": "HSN1F", "name": "New One-Family Houses Sold", "fred": "HSN1F", "invert": false, "yoy": 0.8, "z": 0.05, "since": 1963, "lead": 10, "tag": "LEADS", "live": true}, {"id": "COMPUTSA", "name": "Housing Completions", "fred": "COMPUTSA", "invert": false, "yoy": 2.5, "z": 0.2, "since": 1968, "lead": -9, "tag": "LAGS", "live": true}, {"id": "EXHOSLUSM495S", "name": "Existing Home Sales (NAR)", "fred": "EXHOSLUSM495S", "invert": false, "yoy": -1.5, "z": -0.1, "since": 1999, "lead": 2, "tag": "COINCIDENT", "live": true}, {"id": "UMCSENT", "name": "Univ. Michigan Sentiment (proxy)", "fred": "UMCSENT", "invert": false, "yoy": 2.0, "z": 0.1, "since": 1978, "lead": 26, "tag": "LEADS", "live": true}, {"id": "NAHB", "name": "NAHB / Wells Fargo HMI", "fred": "NAHBHMI", "invert": false, "yoy": null, "z": null, "since": 1985, "lead": 15, "tag": "LEADS", "live": false}];
const THRESH = {"soft_landing_upper": 0.0, "soft_landing_lower": -12.0, "recession_floor": -25.0};
const DEMO_META = {
  source:"DEMO_SCAFFOLD",
  title:"U.S. Housing Market Index",
  subtitle:"8-component cyclical housing-momentum index · FRED replication of RecessionALERT USHMI",
  as_of:"2026-04", published:"2026-05-12",
};

function parseSeries(csv){
  return csv.trim().split("\n").map(l=>{
    const p=l.split(",");
    return { d:p[0], c:+p[1], s:+p[2], df:+p[3], p:+p[4], pa:+p[5], lead:+p[6], ehs:+p[7], r:+p[8] };
  });
}
const DEMO = { meta:DEMO_META, series:parseSeries(SERIES_CSV), components:COMPONENTS, thresholds:THRESH };

/* ---- LIVE DATA -----------------------------------------------------
   Points at the housing.json the daily-ingest workflow commits to the
   macro-regime repo. If the fetch fails the component falls back to DEMO.
*/
const DATA_URL = "https://raw.githubusercontent.com/smallfishmacro-Git/macro-regime/main/data/housing.json";

/* ---- helpers -------------------------------------------------------- */
const NN  = v => v!=null && !Number.isNaN(v);                 // is real number
const SP  = v => NN(v) ? (v>0?"+":"") + v.toFixed(2) : "n/a"; // signed 2dp, null-safe
const PCT = (v,dp=1) => NN(v) ? v.toFixed(dp)+"%" : "n/a";    // null-safe percent
/* latest non-null value of `key` (+ the prior non-null + its date) */
function lastValid(rows, key){
  let vi=-1, pi=-1;
  for(let i=rows.length-1;i>=0;i--){
    if(NN(rows[i][key])){ if(vi<0) vi=i; else { pi=i; break; } }
  }
  return { v: vi>=0?rows[vi][key]:null, d: vi>=0?rows[vi].d:null, p: pi>=0?rows[pi][key]:null };
}
const MONTHS = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
const fmtMon = d => { const [y,m]=d.split("-"); return MONTHS[+m-1]+"-"+y.slice(2); };

const RANGES = [["1Y",12],["3Y",36],["5Y",60],["10Y",120],["MAX",9999]];

const BENCH = {
  lead:{ key:"lead", name:"USHMI-Leading", axis:"LEADING SUB-INDEX", color:T.amber, reversed:false,
         fmt:v=>SP(v), dom:(mn,mx)=>[Math.floor(mn-3), Math.ceil(mx+3)] },
  ehs :{ key:"ehs",  name:"Existing Sales YoY", axis:"EXISTING HOME SALES YoY %", color:T.green, reversed:false,
         fmt:v=>PCT(v,0), dom:(mn,mx)=>[Math.min(Math.floor(mn-3),-5), Math.max(Math.ceil(mx+3),5)] },
  df  :{ key:"df",   name:"% in Recession", axis:"% OF COMPONENTS IN RECESSION", color:T.red, reversed:false,
         fmt:v=>PCT(v,0), dom:()=>[0,100] },
  p   :{ key:"p",    name:"Recession Prob.", axis:"RECESSION PROBABILITY 6M %", color:T.red, reversed:false,
         fmt:v=>PCT(v,0), dom:()=>[0,100] },
};

function recRuns(rows){
  const out=[]; let st=null;
  rows.forEach((r,i)=>{
    if(r.r===1 && st===null) st=r.d;
    if(r.r===0 && st!==null){ out.push([st, rows[i-1].d]); st=null; }
  });
  if(st!==null) out.push([st, rows[rows.length-1].d]);
  return out;
}

function regimeOf(s, th){
  const c = s[s.length-1].c;
  const c3 = s.length>3 ? c - s[s.length-4].c : 0;
  if(c < th.recession_floor)    return {label:"HOUSING RECESSION", color:T.red,   note:"Below historical housing-recession floor"};
  if(c < th.soft_landing_lower) return {label:"CONTRACTION",       color:T.red,   note:"Broad housing deceleration"};
  if(c < th.soft_landing_upper) return c3>0
       ? {label:"STABILISING · CAUTION", color:T.amber, note:"Below zero but turning up"}
       : {label:"SOFT-LANDING ZONE",     color:T.amber, note:"Sub-trend housing momentum"};
  return c3>0 ? {label:"EARLY UPTURN", color:T.green, note:"Above zero and rising"}
              : {label:"EXPANSION",    color:T.green, note:"Above zero"};
}

function narrative(data){
  const s=data.series, last=s[s.length-1], prev=s[s.length-2];
  const live = (data.components||[]).filter(c=>c.live!==false);
  const denom = live.length || 8;
  const dir = last.c>prev.c ? "rose to" : last.c<prev.c ? "eased to" : "held at";
  const contracting = Math.round(last.df/100*denom);
  const recentlyCrossed = last.c>=0 && s.slice(-4,-1).some(x=>x.c<0);
  const lead = recentlyCrossed
    ? ", its first positive territory after a prolonged decline"
    : (last.c<0 ? ", still below the zero line" : "");
  const leadClause = NN(last.lead)
    ? ` The two most-leading components (supply + purchase sentiment) read ${SP(last.lead)}.`
    : "";
  return `USHMI ${dir} ${SP(last.c)} in ${fmtMon(last.d)}${lead}. `
       + `${contracting} of ${denom} live components are contracting (breadth ${last.df.toFixed(0)}%), and the `
       + `model-implied probability of recession within 6 months is ${last.p.toFixed(0)}% `
       + `(blended ${last.pa.toFixed(0)}%).${leadClause} Housing has led the business cycle by ~14 months on average.`;
}

/* ---- tiny UI atoms -------------------------------------------------- */
function Stat({label, value, sub, color, deltaTxt, deltaColor}){
  return (
    <div style={{background:T.panel, border:`1px solid ${T.border}`, padding:"11px 13px", flex:1, minWidth:140}}>
      <div style={{color:T.dim, fontSize:9.5, letterSpacing:1.4, textTransform:"uppercase"}}>{label}</div>
      <div style={{display:"flex", alignItems:"baseline", gap:8, marginTop:5}}>
        <div style={{color:color||T.text, fontSize:22, fontWeight:700, lineHeight:1}}>{value}</div>
        {deltaTxt!=null && <div style={{color:deltaColor, fontSize:11, fontWeight:600}}>{deltaTxt}</div>}
      </div>
      {sub && <div style={{color:T.dim, fontSize:9.5, marginTop:5, letterSpacing:0.4}}>{sub}</div>}
    </div>
  );
}
function Pill({active, onClick, children}){
  return (
    <button onClick={onClick} style={{
      background: active?T.cyan:"transparent", color: active?"#000":T.dim,
      border:`1px solid ${active?T.cyan:T.border}`, fontFamily:T.mono, fontSize:10.5,
      fontWeight:600, letterSpacing:0.6, padding:"3px 10px", cursor:"pointer"}}>
      {children}
    </button>
  );
}
function ChartTip({active, payload, label, bench}){
  if(!active||!payload||!payload.length) return null;
  const row = payload[0] && payload[0].payload;
  if(!row) return null;
  const b = BENCH[bench];
  return (
    <div style={{background:"#000", border:`1px solid ${T.faint}`, padding:"8px 10px", fontFamily:T.mono, fontSize:11}}>
      <div style={{color:T.text, fontWeight:700, marginBottom:5}}>{fmtMon(label)}{row.r?"  · recession":""}</div>
      <Row k="USHMI" v={SP(row.c)} c={row.c>=0?T.green:T.red}/>
      <Row k={b.name} v={b.fmt(row[b.key])} c={b.color}/>
      <Row k="Breadth" v={row.df.toFixed(0)+"%"} c={T.dim}/>
      <Row k="Rec. prob 6m" v={row.p.toFixed(0)+"%"} c={T.dim}/>
    </div>
  );
}
const Row = ({k,v,c}) => (
  <div style={{display:"flex", justifyContent:"space-between", gap:18}}>
    <span style={{color:T.dim}}>{k}</span><span style={{color:c, fontWeight:600}}>{v}</span>
  </div>
);
const Panel = ({title, right, children, pad=true}) => (
  <div style={{background:T.panel2, border:`1px solid ${T.border}`}}>
    {(title||right) &&
      <div style={{display:"flex", justifyContent:"space-between", alignItems:"center",
                   padding:"8px 12px", borderBottom:`1px solid ${T.border}`}}>
        <div style={{color:T.text, fontSize:10.5, letterSpacing:1.4, textTransform:"uppercase"}}>{title}</div>
        {right}
      </div>}
    <div style={{padding: pad?12:0}}>{children}</div>
  </div>
);

/* ===================================================================== */
export default function HousingTab(){
  const [data, setData] = useState(DEMO);
  const [bench, setBench] = useState("lead");
  const [rangeI, setRangeI] = useState(4);   // default MAX
  const isDemo = data.meta && data.meta.source === "DEMO_SCAFFOLD";

  useEffect(()=>{
    if(!DATA_URL) return;
    let live=true;
    fetch(DATA_URL).then(r=>r.ok?r.json():Promise.reject()).then(j=>{
      if(live && j && j.series && j.series.length) setData(j);
    }).catch(()=>{ /* keep DEMO */ });
    return ()=>{ live=false; };
  },[]);

  const S = data.series;
  const th = data.thresholds || THRESH;
  const months = RANGES[rangeI][1];
  const view = useMemo(()=> months>=9999 ? S : S.slice(Math.max(0,S.length-months)), [S, months]);

  const last = S[S.length-1], prev = S[S.length-2];
  const reg = useMemo(()=> regimeOf(S, th), [S, th]);

  /* live-component bookkeeping (NAHB has no free FRED feed) */
  const liveComps = (data.components||[]).filter(c=>c.live!==false);
  const denom = liveComps.length || 8;
  const contracting = liveComps.filter(c=>NN(c.z) && c.z<0).length;

  /* axis domains */
  const cs = view.map(r=>r.c);
  let lo=Math.min(...cs,0)-3, hi=Math.max(...cs,0)+3;
  const leftDom=[Math.floor(lo), Math.ceil(hi)];
  const b=BENCH[bench];
  const bs=view.map(r=>r[b.key]).filter(NN);
  const rightDom= bs.length ? b.dom(Math.min(...bs), Math.max(...bs)) : [0,1];

  /* ticks: year labels at a sensible cadence */
  const span=view.length;
  const step= span<=40?1: span<=90?2: span<=200?5:10;
  const ticks=view.filter(r=>r.d.endsWith("-01") && (+r.d.slice(0,4))%step===0).map(r=>r.d);

  const runs=recRuns(view);

  /* deltas */
  const dC=last.c-prev.c, dDf=last.df-prev.df, dP=last.p-prev.p, dL=last.lead-prev.lead;
  const dCol = (x, good="up") => !NN(x)||x===0?T.dim : (good==="up"? (x>0?T.green:T.red) : (x>0?T.red:T.green));

  return (
    <div style={{background:T.bg, color:T.text, fontFamily:T.mono, padding:"16px 18px",
                 minHeight:"100%", boxSizing:"border-box"}}>

      {/* header */}
      <div style={{display:"flex", justifyContent:"space-between", alignItems:"flex-start",
                   borderBottom:`1px solid ${T.border}`, paddingBottom:12}}>
        <div>
          <div style={{display:"flex", alignItems:"center", gap:10}}>
            <span style={{color:T.cyan, fontSize:15, fontWeight:700, letterSpacing:1.5}}>HOUSING</span>
            <span style={{color:T.faint}}>·</span>
            <span style={{color:T.text, fontSize:13, fontWeight:600, letterSpacing:0.5}}>{data.meta.title}</span>
          </div>
          <div style={{color:T.dim, fontSize:10.5, marginTop:5, letterSpacing:0.4}}>{data.meta.subtitle}</div>
        </div>
        <div style={{textAlign:"right"}}>
          <div style={{display:"inline-flex", alignItems:"center", gap:8}}>
            {isDemo &&
              <span title="Synthetic scaffold — set DATA_URL / run the pipeline to go live"
                    style={{color:T.amber, border:`1px solid ${T.amber}`, fontSize:9, fontWeight:700,
                            letterSpacing:1, padding:"2px 6px"}}>DEMO DATA</span>}
            <span style={{background:reg.color, color:"#000", fontSize:11, fontWeight:700,
                          letterSpacing:1, padding:"3px 10px"}}>{reg.label}</span>
          </div>
          <div style={{color:T.dim, fontSize:10, marginTop:6}}>AS OF {fmtMon(data.meta.as_of).toUpperCase()} · pub {data.meta.published}</div>
        </div>
      </div>

      {/* narrative line */}
      <div style={{color:T.text, fontSize:11.5, lineHeight:1.55, margin:"12px 0", opacity:0.92}}>
        <span style={{color:reg.color, fontWeight:700}}>▍</span> {narrative(data)}
        <span style={{color:T.dim}}>  {reg.note}.</span>
      </div>

      {/* KPI row */}
      <div style={{display:"flex", gap:8, flexWrap:"wrap"}}>
        <Stat label="USHMI Composite" value={SP(last.c)} color={last.c>=0?T.green:T.red}
              sub="standardized 8-component momentum" deltaTxt={(dC>=0?"▲":"▼")+" "+Math.abs(dC).toFixed(2)+" MoM"} deltaColor={dCol(dC)}/>
        <Stat label="USHMI-Leading" value={SP(last.lead)} color={last.lead>=0?T.green:T.red}
              sub="supply + purchase sentiment" deltaTxt={(dL>=0?"▲":"▼")+" "+Math.abs(dL).toFixed(2)} deltaColor={dCol(dL)}/>
        <Stat label="% Components in Recession" value={last.df.toFixed(0)+"%"} color={T.text}
              sub={contracting+" of "+denom+" live contracting"} deltaTxt={(dDf>0?"+":"")+dDf.toFixed(1)+" pp"} deltaColor={dCol(dDf,"down")}/>
        <Stat label="Recession Prob · 6m" value={last.p.toFixed(0)+"%"} color={last.p>=50?T.red:last.p>=33?T.amber:T.green}
              sub={"blended "+last.pa.toFixed(0)+"% with breadth"} deltaTxt={(dP>0?"+":"")+dP.toFixed(0)+" pp"} deltaColor={dCol(dP,"down")}/>
        <Stat label="Headline Index" value={last.s.toFixed(0)} color={T.cyan}
              sub="cumulative USHMI · level"/>
      </div>

      {/* hero chart */}
      <div style={{marginTop:14}}>
        <Panel
          title={"USHMI  vs  "+b.name}
          right={
            <div style={{display:"flex", gap:14, alignItems:"center"}}>
              <div style={{display:"flex", gap:5}}>
                {Object.keys(BENCH).map(k=>
                  <Pill key={k} active={bench===k} onClick={()=>setBench(k)}>{BENCH[k].name}</Pill>)}
              </div>
              <span style={{width:1, height:16, background:T.border}}/>
              <div style={{display:"flex", gap:5}}>
                {RANGES.map((r,i)=><Pill key={r[0]} active={rangeI===i} onClick={()=>setRangeI(i)}>{r[0]}</Pill>)}
              </div>
            </div>
          }>
          {/* legend */}
          <div style={{display:"flex", gap:18, padding:"2px 2px 10px", fontSize:10, color:T.dim}}>
            <Lg c={T.cyan} t="USHMI composite (left)"/>
            <Lg c={b.color} t={b.axis+" (right"+(b.reversed?", inverted":"")+")"}/>
            <Lg c={T.rec} t="NBER recession" sq/>
            <span style={{marginLeft:"auto", color:T.faint}}>soft-landing band shaded · floor at {th.recession_floor}</span>
          </div>
          <ResponsiveContainer width="100%" height={380}>
            <ComposedChart data={view} margin={{top:8,right:58,left:4,bottom:4}}>
              <defs>
                <linearGradient id="hcFill" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%"  stopColor={T.cyan} stopOpacity={0.28}/>
                  <stop offset="100%" stopColor={T.cyan} stopOpacity={0.02}/>
                </linearGradient>
              </defs>
              <CartesianGrid stroke={T.grid} strokeDasharray="2 4" vertical={false}/>
              {runs.map(([x0,x1],i)=>
                <ReferenceArea key={i} x1={x0} x2={x1} yAxisId="left" fill={T.rec} fillOpacity={1} strokeOpacity={0}/>)}
              {/* soft-landing band + lines */}
              <ReferenceArea yAxisId="left" y1={th.soft_landing_lower} y2={th.soft_landing_upper}
                             fill={T.amber} fillOpacity={0.06} strokeOpacity={0}/>
              <ReferenceLine yAxisId="left" y={0} stroke={T.faint} strokeDasharray="3 3"/>
              <ReferenceLine yAxisId="left" y={th.recession_floor} stroke={T.red} strokeOpacity={0.45} strokeDasharray="4 4"/>

              <XAxis dataKey="d" ticks={ticks} tickFormatter={d=>d.slice(0,4)}
                     tick={{fill:T.dim, fontSize:10}} stroke={T.border} minTickGap={10}/>
              <YAxis yAxisId="left" domain={leftDom} tick={{fill:T.cyan, fontSize:10}} stroke={T.border}
                     width={34} label={{value:"USHMI", angle:-90, position:"insideLeft", fill:T.dim, fontSize:9, dy:20}}/>
              <YAxis yAxisId="right" orientation="right" domain={rightDom} reversed={b.reversed}
                     tickFormatter={b.fmt} tick={{fill:b.color, fontSize:10}} stroke={T.border} width={48}/>

              <Tooltip content={<ChartTip bench={bench}/>} cursor={{stroke:T.faint, strokeWidth:1}}/>

              <Area  yAxisId="left"  type="monotone" dataKey="c" stroke={T.cyan} strokeWidth={1.6}
                     fill="url(#hcFill)" dot={false} isAnimationActive={false} name="USHMI"/>
              <Line  yAxisId="right" type="monotone" dataKey={b.key} stroke={b.color} strokeWidth={1.4}
                     dot={false} isAnimationActive={false} name={b.name}
                     strokeDasharray={bench==="lead"?"4 2":undefined}/>

              <ReferenceDot yAxisId="left" x={view[view.length-1].d} y={view[view.length-1].c} r={3} fill={T.cyan} stroke="#000"
                            label={{value:SP(view[view.length-1].c), position:"left", fill:T.cyan, fontSize:11, fontWeight:700}}/>
              {(()=>{ const be=lastValid(view,b.key); return NN(be.v) && (
                <ReferenceDot yAxisId="right" x={be.d} y={be.v} r={3} fill={b.color} stroke="#000"
                              label={{value:b.fmt(be.v), position:"right", fill:b.color, fontSize:11, fontWeight:700}}/>
              ); })()}

              <Brush dataKey="d" height={20} stroke={T.faint} fill="#070707"
                     travellerWidth={8} tickFormatter={fmtMon}/>
            </ComposedChart>
          </ResponsiveContainer>
        </Panel>
      </div>

      {/* lower grid: components + (recession-prob mini, headline mini) */}
      <div style={{display:"grid", gridTemplateColumns:"1.25fr 1fr", gap:12, marginTop:12}}>

        {/* component breadth */}
        <Panel title={"Component breadth · "+contracting+"/"+denom+" contracting"}
               right={<span style={{color:T.dim, fontSize:9.5}}>YoY %Δ · standardized · typical lead</span>}>
          <div style={{display:"grid", gridTemplateColumns:"1fr 1fr", gap:"9px 18px"}}>
            {data.components.map(c=>{
              const off = c.live===false;
              const pos = NN(c.z) && c.z>=0; const w = NN(c.z)? Math.min(Math.abs(c.z),1.4)/1.4*50 : 0;
              const leadTxt = c.lead==null ? "" : c.lead>3 ? `leads ~${c.lead}m`
                            : c.lead < -3 ? `lags ~${-c.lead}m` : "coincident";
              return (
                <div key={c.id} style={{opacity: off?0.42:1}}>
                  <div style={{display:"flex", justifyContent:"space-between", alignItems:"baseline"}}>
                    <span style={{color:T.text, fontSize:10.5}} title={c.fred}>
                      {c.name}{c.invert && <span style={{color:T.dim, fontSize:8.5}} title="inverted (rise = weaker housing)"> ⁻¹</span>}
                    </span>
                    <span style={{color: off?T.dim : (pos?T.green:T.red), fontSize:11, fontWeight:700}}>
                      {off ? "n/a" : (c.yoy>0?"+":"")+c.yoy.toFixed(1)+"%"}
                    </span>
                  </div>
                  {/* centered contribution bar */}
                  <div style={{position:"relative", height:5, background:"#141414", marginTop:5}}>
                    <div style={{position:"absolute", left:"50%", top:0, bottom:0, width:1, background:T.faint}}/>
                    {!off && <div style={{position:"absolute", top:0, bottom:0, background:pos?T.green:T.red,
                                 left: pos? "50%" : (50-w)+"%", width:w+"%", opacity:0.85}}/>}
                  </div>
                  <div style={{color:T.faint, fontSize:8.5, marginTop:3, letterSpacing:0.3}}>
                    {off ? "no free FRED feed · add a CSV/vendor" : `${c.fred} · since ${c.since} · ${leadTxt}`}
                  </div>
                </div>
              );
            })}
          </div>
          <div style={{borderTop:`1px solid ${T.border}`, marginTop:11, paddingTop:9,
                       color:T.dim, fontSize:9.5, lineHeight:1.5}}>
            Each component = 12-month % change, standardized, then equal-weighted into the composite.
            <span style={{color:T.green}}> green</span> = expansionary contribution,
            <span style={{color:T.red}}> red</span> = contractionary. Monthly supply is inverted
            (a rise in months-of-supply signals weaker demand).
          </div>
        </Panel>

        <div style={{display:"flex", flexDirection:"column", gap:12}}>
          {/* recession probability */}
          <Panel title="Recession probability · 6-month horizon">
            <ResponsiveContainer width="100%" height={132}>
              <ComposedChart data={view} margin={{top:6,right:10,left:-18,bottom:0}}>
                <defs>
                  <linearGradient id="hpFill" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0%" stopColor={T.red} stopOpacity={0.35}/>
                    <stop offset="100%" stopColor={T.red} stopOpacity={0.02}/>
                  </linearGradient>
                </defs>
                <CartesianGrid stroke={T.grid} strokeDasharray="2 4" vertical={false}/>
                {runs.map(([x0,x1],i)=><ReferenceArea key={i} x1={x0} x2={x1} fill={T.rec} strokeOpacity={0}/>)}
                <ReferenceLine y={67} stroke={T.amber} strokeOpacity={0.5} strokeDasharray="3 3"
                               label={{value:"67%", position:"right", fill:T.amber, fontSize:8}}/>
                <ReferenceLine y={50} stroke={T.faint} strokeDasharray="3 3"/>
                <XAxis dataKey="d" ticks={ticks} tickFormatter={d=>"'"+d.slice(2,4)}
                       tick={{fill:T.dim, fontSize:9}} stroke={T.border} hide/>
                <YAxis domain={[0,100]} ticks={[0,50,100]} tick={{fill:T.dim, fontSize:9}} stroke={T.border} width={28}/>
                <Tooltip content={<ChartTip bench="p"/>} cursor={{stroke:T.faint}}/>
                <Area type="monotone" dataKey="p" stroke={T.red} strokeWidth={1.3} fill="url(#hpFill)" dot={false} isAnimationActive={false}/>
                <Line type="monotone" dataKey="pa" stroke={T.amber} strokeWidth={1} dot={false} strokeDasharray="3 2" isAnimationActive={false}/>
              </ComposedChart>
            </ResponsiveContainer>
            <div style={{display:"flex", gap:14, fontSize:9, color:T.dim, paddingTop:4}}>
              <Lg c={T.red} t="implied prob."/><Lg c={T.amber} t="blended w/ breadth"/>
            </div>
          </Panel>

          {/* headline index */}
          <Panel title="Headline index · level">
            <ResponsiveContainer width="100%" height={132}>
              <ComposedChart data={view} margin={{top:6,right:10,left:-12,bottom:0}}>
                <defs>
                  <linearGradient id="hsFill" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0%" stopColor={T.cyan} stopOpacity={0.3}/>
                    <stop offset="100%" stopColor={T.cyan} stopOpacity={0.02}/>
                  </linearGradient>
                </defs>
                <CartesianGrid stroke={T.grid} strokeDasharray="2 4" vertical={false}/>
                {runs.map(([x0,x1],i)=><ReferenceArea key={i} x1={x0} x2={x1} fill={T.rec} strokeOpacity={0}/>)}
                <XAxis dataKey="d" ticks={ticks} tickFormatter={d=>d.slice(0,4)} tick={{fill:T.dim, fontSize:9}} stroke={T.border}/>
                <YAxis tick={{fill:T.dim, fontSize:9}} stroke={T.border} width={36}/>
                <Tooltip content={<ChartTip bench="df"/>} cursor={{stroke:T.faint}}/>
                <Area type="monotone" dataKey="s" stroke={T.cyan} strokeWidth={1.4} fill="url(#hsFill)" dot={false} isAnimationActive={false}/>
              </ComposedChart>
            </ResponsiveContainer>
          </Panel>
        </div>
      </div>

      {/* methodology footer */}
      <div style={{marginTop:14, borderTop:`1px solid ${T.border}`, paddingTop:10,
                   color:T.dim, fontSize:9.5, lineHeight:1.6}}>
        <span style={{color:T.text, letterSpacing:1, textTransform:"uppercase"}}>Methodology</span>  ·
        8 highly cyclical, rate-sensitive housing components in chronological order
        (permits → starts → completions → supply → new &amp; existing sales, plus builder &amp; buyer
        sentiment). Each is taken as a 12-month % change, standardized, sign-aligned, then equal-weighted
        into the composite; the two most-leading (supply + purchase sentiment) form USHMI-Leading. Breadth =
        share contracting; the headline index is the cumulative composite. Housing leads recession by ~14
        months on average (6-month SD, CoV 0.42). {isDemo && <span style={{color:T.amber}}>Showing synthetic scaffold data — run the pipeline for the live FRED feed. </span>}
        <span style={{color:T.faint}}> Sources (FRED): PERMIT · HOUST · MSACSR · COMPUTSA · HSN1F · EXHOSLUSM495S · UMCSENT (University of Michigan consumer sentiment — same survey provider the report names — used as the public proxy for its "buying conditions for houses" sub-question; Fannie Mae's housing-specific HPSI/FMNHSHPSIUS is the closer concept but was discontinued on FRED in 2025). NAHB/Wells Fargo HMI has no free FRED feed and is shown as a placeholder until a CSV/vendor source is wired in. Benchmark USREC. Replication of the RecessionALERT© USHMI concept.</span>
      </div>
    </div>
  );
}

const Lg = ({c,t,sq}) => (
  <span style={{display:"inline-flex", alignItems:"center", gap:6}}>
    <span style={{width:sq?9:13, height:sq?9:3, background:c, display:"inline-block"}}/>{t}
  </span>
);
